mapper.select:
select t.machine_id,t.machine_id machineId,t.org_name,t.org_name orgName,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.aco_id,t.aco_id acoId,t.org_id,t.org_id orgId,
ac.machine_code machineCode,ac.machine_name machineName,t.create_time createTime
from access_control_org t
left join access_control ac on ac.machine_id = t.machine_id and ac.status_cd = '0'
where 1 =1

    and t.machine_id= #{machineId}


    and t.org_name= #{orgName}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.aco_id= #{acoId}


    and t.org_id= #{orgId}

order by t.create_time desc

    limit #{page}, #{row}

